css:
.aha-hero-banner{
  --aha-hero-banner-surface:var(--aha-vivid-pink-100);
  --aha-hero-banner-hooks:var(--aha-vivid-pink-dark);
  --aha-hero-banner-ink:var(--aha-text-inverse);
  --aha-hero-banner-cta-bg:var(--aha-white);
  --aha-hero-banner-cta-bg-hover:var(--aha-white);
  --aha-hero-banner-cta-text:var(--aha-color-primary);
  --aha-hero-banner-cta-text-hover:var(--aha-color-primary-hover);
  --aha-hero-banner-focus:var(--aha-white);
  container:aha-hero-banner / inline-size;
  position:relative;isolation:isolate;overflow:hidden;
  font-family:var(--aha-font-product);
  background:var(--aha-white);
}
.aha-hero-banner--pale{
  --aha-hero-banner-surface:var(--aha-vivid-pink-5);
  --aha-hero-banner-hooks:var(--aha-vivid-pink-5);
  --aha-hero-banner-ink:var(--aha-text-default);
  --aha-hero-banner-cta-bg:var(--aha-button-primary-bg);
  --aha-hero-banner-cta-bg-hover:var(--aha-button-primary-bg-hover);
  --aha-hero-banner-cta-text:var(--aha-button-primary-text);
  --aha-hero-banner-cta-text-hover:var(--aha-button-primary-text);
  --aha-hero-banner-focus:var(--aha-focus);
}
.aha-hero-banner *{box-sizing:border-box}
:where(.aha-hero-banner) h1,:where(.aha-hero-banner) p{margin:0}
.aha-hero-banner__surface{position:absolute;inset:0;z-index:-1;overflow:hidden;background:var(--aha-hero-banner-surface)}
.aha-hero-banner__hooks{
  position:absolute;left:75%;top:55%;width:180cqw;height:auto;
  transform:translate(-51.6%,-42.6%);
  fill:var(--aha-hero-banner-hooks);
}
.aha-hero-banner--vertical .aha-hero-banner__hooks{left:50%;width:312cqw}
.aha-hero-banner__inner{
  display:flex;flex-direction:row;align-items:center;justify-content:space-between;gap:var(--aha-space-64);
  width:100%;max-width:1280px;margin:0 auto;
  padding:var(--aha-space-64);
}
.aha-hero-banner__copy{display:flex;flex-direction:column;align-items:flex-start;width:100%;max-width:720px;color:var(--aha-hero-banner-ink)}
.aha-hero-banner__title{
  margin-bottom:var(--aha-space-24);
  font-size:var(--aha-size-h1);font-weight:var(--aha-weight-semibold);line-height:var(--aha-line-height-heading);
  letter-spacing:var(--aha-letter-spacing-headlines);
  color:var(--aha-hero-banner-ink);
}
.aha-hero-banner__text{
  margin-bottom:var(--aha-space-32);
  font-size:var(--aha-size-l);font-weight:var(--aha-weight-regular);line-height:var(--aha-line-height-body);
  letter-spacing:var(--aha-letter-spacing-paragraph);
  color:var(--aha-hero-banner-ink);
}
.aha-hero-banner__cta{
  display:flex;align-items:center;justify-content:center;
  height:var(--aha-control-height-button-xl);padding:0 var(--aha-space-20);
  border-radius:var(--aha-radius-default);
  font-size:var(--aha-size-h6);font-weight:var(--aha-weight-regular);line-height:1;white-space:nowrap;
  text-decoration:none;
  color:var(--aha-hero-banner-cta-text);background:var(--aha-hero-banner-cta-bg);
  box-shadow:var(--aha-button-elevate-primary);
  transition:background-color var(--aha-motion-mid),color var(--aha-motion-mid);
}
.aha-hero-banner__cta:hover,.aha-hero-banner__cta:active{background:var(--aha-hero-banner-cta-bg-hover);color:var(--aha-hero-banner-cta-text-hover)}
.aha-hero-banner__cta:focus-visible{outline:var(--aha-space-2) solid var(--aha-hero-banner-focus);outline-offset:var(--aha-space-2)}
.aha-hero-banner__card{
  width:100%;max-width:680px;padding:var(--aha-space-12);
  border-radius:var(--aha-radius-xl);background:var(--aha-white);
}
.aha-hero-banner__image{
  width:100%;aspect-ratio:4 / 3;
  border-radius:var(--aha-radius-lg);background:var(--aha-bg-container-secondary);
}
.aha-hero-banner--vertical .aha-hero-banner__inner{flex-direction:column;justify-content:flex-start;gap:var(--aha-space-48)}
.aha-hero-banner--vertical .aha-hero-banner__copy{align-items:center;text-align:center}
.aha-hero-banner--vertical .aha-hero-banner__card{max-width:960px}
.aha-hero-banner--vertical .aha-hero-banner__image{aspect-ratio:16 / 9}
@container aha-hero-banner (max-width:991px){
  .aha-hero-banner__hooks,.aha-hero-banner--vertical .aha-hero-banner__hooks{width:450cqw}
  .aha-hero-banner__inner{flex-direction:column;align-items:flex-start;justify-content:flex-start;max-width:728px;gap:var(--aha-space-48)}
  .aha-hero-banner__title{font-size:var(--aha-size-h3)}
  .aha-hero-banner__card,.aha-hero-banner--vertical .aha-hero-banner__card{max-width:none}
  .aha-hero-banner--vertical .aha-hero-banner__inner{align-items:center}
}
@container aha-hero-banner (max-width:479px){
  .aha-hero-banner__inner{padding:var(--aha-space-32) var(--aha-space-32) var(--aha-space-64);gap:var(--aha-space-32)}
  .aha-hero-banner__title{font-size:var(--aha-size-h4)}
}
